void rtpin_satip_get_server_ip(const char *sURL, char *Server)
{
        char schema[10], *test, text[1024], *retest;
        u32 i, len;
        Bool is_ipv6;
        if (!sURL) return;

        strcpy(Server, "");

        //extract the schema
        i = 0;
        while (i <= strlen(sURL)) {
                if (sURL[i] == ':')
                        goto found;
                schema[i] = sURL[i];
                i += 1;
        }
        return;

found:
        schema[i] = 0;
        if (stricmp(schema, "satip")) {
                GF_LOG(GF_LOG_ERROR, GF_LOG_RTP, ("[RTP] Wrong SATIP schema %s - not setting up\n", schema));
                return;
        }
        test = strstr(sURL, "://");
        test += 3;

        //check for port
        retest = strrchr(test, ':');
        /*IPV6 address*/
        if (retest && strchr(retest, ']')) retest = NULL;

        if (retest && strstr(retest, "/")) {
                retest += 1;
                i = 0;
                while (i<strlen(retest)) {
                        if (retest[i] == '/') break;
                        text[i] = retest[i];
                        i += 1;
                }
                text[i] = 0;
        }
        //get the server name
        is_ipv6 = GF_FALSE;
        len = (u32)strlen(test);
        i = 0;
        while (i<len) {
                if (test[i] == '[') is_ipv6 = GF_TRUE;
                else if (test[i] == ']') is_ipv6 = GF_FALSE;
                if ((test[i] == '/') || (!is_ipv6 && (test[i] == ':'))) break;
                text[i] = test[i];
                i += 1;
        }
        text[i] = 0;
        strcpy(Server, text);
}


